+'use strict';
+
+function parsePort(text) {
+  const n = Number(text);
+  if (Number.isNaN(n)) throw new TypeError(`not a number: ${text}`);
+  if (n < 0 || n > 65535) throw new RangeError(`port out of range: ${n}`);
+  return n;
+}
+
+module.exports = { parsePort };
